INSERT INTO feature VALUES('abstract-closures','machine','Abstract closures in the sequent IL','sequent-machine','partial','notable',NULL,'A closure former of the focused IL carries an environment of values its code reads by index, and entering it binds the environment and the frame''s arguments together; conversion moves each intuitionistic context variable the code names into the environment, one at a time and the greatest first, and a converted program runs to what it ran to as written, on every tier for generated programs and on the portable executor for every `runs` item of the corpus. A closure at the end of a bind chain enters at the chain''s hole when the chain is applied, as the distant β of λJn does (Espírito Santo, Kesner and Peyrot, 2024). The frame''s continuation stays outside the chain. Every generated program runs entered to what it runs to as written, on every tier, and every `runs` item of the corpus does on the portable executor. The bindings run a copy of the entered body''s root, so a closure that keeps the body shares no node of it with them. The checked surface writes no bind chain (#3636). A closure''s type records no summary of its environment, a linear capture stays captured by support, and environment sharing, lambda sets and a run path that converts are owed.','core-sequent surface-dispatcher surface-evaluate','corpus/ledger/features/abstract-closures.gandr crates/core-sequent/tests/closures.rs crates/surface-evaluate/src/evaluate.rs','corpus/ledger/features/abstract-closures.gandr','#3077 #2770 #3636');
